import re

def rot_n(s, n):
    result = []
    for c in s:
        if 'A' <= c <= 'Z':
            result.append(chr((ord(c)-ord('A')+n)%26 + ord('A')))
        elif 'a' <= c <= 'z':
            result.append(chr((ord(c)-ord('a')+n)%26 + ord('a')))
        else:
            result.append(c)
    return ''.join(result)

def atbash(s):
    result = []
    for c in s:
        if 'A' <= c <= 'Z':
            result.append(chr(ord('Z')-(ord(c)-ord('A'))))
        elif 'a' <= c <= 'z':
            result.append(chr(ord('z')-(ord(c)-ord('a'))))
        else:
            result.append(c)
    return ''.join(result)

def find_flag(text):
