    # returns a string of the bytewise NOT (XOR with 0xFF)
    return ''.join(chr(ord(c) ^ 0xFF) for c in s)

def chained_xor(s, chain):
    # XOR each char in s sequentially with all values in chain
    return ''.join(chr(ord(c) ^ x) for c in s for x in chain)

def chained_xor_onebyone(s, chain):
    # XOR one by one across the chain
    out = ''
    for c in s:
        v = ord(c)
        for x in chain:
            v ^= x
        out += chr(v)
    return out

def swap_case(s):
    return s.swapcase()


def try_all_transforms(variant):
    print(f"Trying variant: {variant}")
    transformations = []

    # 1. bitwise NOT only
    not1 = bitwise_not(variant)
    transformations.append(('bitwise_not', not1))

    # 2. chained XOR from original
    xor1 = chained_xor_onebyone(variant, [0x20, 0x40, 0x80])
    transformations.append(('x20_x40_x80', xor1))

    # 3. chained XOR after bitwise NOT
    not_xor = chained_xor_onebyone(not1, [0x20, 0x40, 0x80])
    transformations.append(('not_then_xor', not_xor))

    # 4. bitwise NOT after chained XOR
    xor_then_not = bitwise_not(xor1)
    transformations.append(('xor_then_not', xor_then_not))

    # 5. Swap case after all above
    for name, t in transformations[:]:
        swap = swap_case(t)
        transformations.append((name+'_swapcase', swap))

    for name, t in transformations:
        print(f'{name}: {repr(t)}')
        if FLAG_FORMAT in t or FLAG_FORMAT.upper() in t:
